export class StateMachine {
    activeState = null;
    states = new Map();
    async enterAsync(StateClass) {
        const state = this.changeState(StateClass);
        if (state) {
            await state.enterAsync();
        }
    }
    async enterAsyncWithPayload(StateClass, payload) {
        const state = this.changeState(StateClass);
        if (state) {
            await state.enterAsync(payload);
        }
    }
    enter(StateClass) {
        const state = this.changeState(StateClass);
        state?.enter();
    }
    enterWithPayload(StateClass, payload) {
        const state = this.changeState(StateClass);
        state?.enter(payload);
    }
    changeState(StateClass) {
        const newState = this.getState(StateClass);
        if (this.activeState === newState) {
            return null;
        }
        this.activeState?.exit();
        const state = this.getState(StateClass);
        this.activeState = state;
        if (!state) {
            throw new Error(`State ${StateClass.name} is not registered.`);
        }
        return state;
    }
    getState(StateClass) {
        return this.states.get(StateClass);
    }
}
